package llm

// One command buffer a **pass**, and the attribution that has to survive it:
// LLM.md L7d.
//
// L7c-5 took the graph from a submit a dispatch to a submit a block — ~1130
// to ~490 — and priced the rest at 31-43 us each, which is ~15-21 ms of a
// 99 ms decode token. Nothing in the shim ever prevented going further: it
// binds each dispatch's own pipeline, descriptor set and push constants, so a
// sequence may mix blocks as freely as it mixes kernels of one block. What
// stopped it was the *measurement*. Every number this vertical has been tuned
// by comes from the host wall clock around a block's `Run`, and a block that
// no longer submits has no wall clock of its own.
//
// So the recorder moves both. Each block's `Run` appends to it instead of
// submitting when one is installed, and the submit asks the shim for a
// timestamp after **every** dispatch (vk.DispatchMultiMarked) rather than only
// at the two ends. The per-block figures that come back are then GPU time
// inside one command buffer rather than host time around many, which is the
// same thing llama.cpp's own `GGML_VK_PERF_LOGGER` reports for its graph — the
// baseline half of every comparison in LLM.md — and strictly the better
// number: it cannot be inflated by a fence wait, a Go allocation or a page
// fault on the host.

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"

	"strix-halo-vulkan/vk"
)

// The block names a dispatch can be attributed to. They are the rows of
// GraphStats, and a dispatch carries one because a command buffer does not.
const (
	ownHC   = "hc"
	ownPLE  = "ple"
	ownDN   = "dn"
	ownAttn = "attn"
	ownMoE  = "moe"
	ownHead = "head"
	ownMove = "move"
)

// maxBatch is how many dispatches go into one command buffer. It is a bound
// on the shim's query pool (SHIM_QUERY_SLOTS) and not a tuning knob: a whole
// prefill pass is ~1200 dispatches, so this is one submit for a decode token
// and two for a long prompt, against the ~490 either used to take.
// LLM_MAX_BATCH overrides it, which is how P0 asked whether a hang was about
// the size of one submit rather than about any dispatch in it.
var maxBatch = envInt("LLM_MAX_BATCH", 1024)

// minBatch keeps the row-scaled bound below from degenerating: a submit costs
// ~40 us, so even at 32 dispatches the boundary is under 2% of a pass.
const minBatch = 32

// submitBudget is how much GPU time one command buffer may hold.
//
// **P0.** It is not the query pool and it is not the dispatch count: a submit
// that occupies the gfx ring for more than ~2 s is killed by amdgpu's ring
// watchdog. The kernel says `ring gfx_0.0.0 timeout, signaled seq=N, emitted
// seq=N+3`, resets the ring, and the reset *force-signals the fence* -- so
// vkQueueSubmit returns, vkWaitForFences returns VK_SUCCESS, its own 20-second
// timeout never fires, and the only trace left is the timestamps the killed
// dispatches never wrote. Reading those with VK_QUERY_RESULT_WAIT_BIT is an
// unbounded userspace poll inside RADV, which is the 100%-of-a-core spin that
// looked like a hang in the submit (see shim_query_results_deadline).
//
// Measured at 48 layers, 1024 dispatches a submit: 2560 rows is 1.886 s and
// runs, 2688 rows is 1.964 s and runs, 2816 rows is 2.033 s and is reset. The
// same 1273 dispatches in *one* submit are 787 ms at 512 rows and run, and are
// reset at 2688 rows -- where two submits of 1024 and 249 had just run the same
// work. So the bound is time, and half the cliff is the budget.
const submitBudget = 1000 * time.Millisecond

// A pass's cost is affine in the rows, not proportional to them: fitting the
// whole-pass figures of 789.5 ms at 512 rows, 2342.4 at 2560, 2434.2 at 2688
// and 2687.5 at 3072 over 1273 dispatches gives 322 us a dispatch plus 582 ns
// a dispatch-row, and predicts all four to within 1.5%. It puts a 1024-dispatch
// submit at 2816 rows at 2.008 s, which is the row count that is reset.
const (
	usPerDispatch    = 322
	nsPerDispatchRow = 582
)

// dispatchCost is what one dispatch of a pass over this many rows costs.
func dispatchCost(rows int) time.Duration {
	return usPerDispatch*time.Microsecond + time.Duration(nsPerDispatchRow*rows)*time.Nanosecond
}

// batchFor is how many dispatches fit in submitBudget at this many rows. At
// one row -- every decode step -- it is maxBatch, so nothing about decode
// changes; it starts biting at ~1700 rows and is ~200 at 8192.
func batchFor(rows int) int {
	if rows < 1 {
		rows = 1
	}
	n := int(submitBudget / dispatchCost(rows))
	return min(max(n, minBatch), maxBatch)
}

// BatchFor is that bound at a given number of rows, exported for a caller
// reporting how many command buffers a pass took.
func BatchFor(rows int) int { return batchFor(rows) }

// batchTimes prints each submit's GPU time, which is how the budget above is
// checked against the ring rather than against the model that predicts it.
var batchTimes = os.Getenv("LLM_BATCH_TIMES") != ""

func envInt(name string, def int) int {
	if v, err := strconv.Atoi(os.Getenv(name)); err == nil && v > 0 {
		return v
	}
	return def
}

// recorder collects a pass's dispatches with the block each came from.
type recorder struct {
	d     []vk.MultiDispatch
	owner []string
	// kind is the block's own name for each dispatch -- "moe.up",
	// "attn.qkv" -- which is what P1 needed and what every block's `graph`
	// method has always built for its error messages. A block name is where
	// the time is *not*: the MoE is 11.6 ms of a 31.7 ms token and says
	// nothing about which of its nine kernels that is.
	kind []string
	// rows is what the pass is passing, which is what a dispatch's cost --
	// and so how many of them fit in one submit -- scales with.
	rows int
}

// add appends one block's sequence, with the block's own label per dispatch.
// A nil recorder is the direct path, which is what every block does when the
// graph is not batching and what the per-block benchmarks always do.
//
// `kinds` may be shorter than `d` or nil -- the mover has one dispatch and no
// label of its own -- in which case the owner's name stands in.
func (r *recorder) add(owner string, kinds []string, d []vk.MultiDispatch) bool {
	if r == nil {
		return false
	}
	r.d = append(r.d, d...)
	for i := range d {
		r.owner = append(r.owner, owner)
		k := owner
		if i < len(kinds) {
			k = owner + "." + kinds[i]
		}
		r.kind = append(r.kind, k)
	}
	return true
}

func (r *recorder) len() int {
	if r == nil {
		return 0
	}
	return len(r.d)
}

// DispatchStat is one kernel's share of a pass: how many dispatches carried
// that label and what they cost on the GPU.
type DispatchStat struct {
	Count int
	GPU   time.Duration
}

// submit runs everything recorded, in order, and returns the GPU time each
// block's dispatches took, and the same split by the label each carried. It
// chunks at batchFor(rows), which costs one more fence wait per chunk and
// keeps the marks.
func (r *recorder) submit() (map[string]time.Duration, map[string]DispatchStat, time.Duration, error) {
	byOwner := make(map[string]time.Duration, 8)
	byKind := make(map[string]DispatchStat, 64)
	var total time.Duration
	r.dumpRange()
	batch := batchFor(r.rows)
	for i := 0; i < len(r.d); i += batch {
		j := minInt(i+batch, len(r.d))
		el, each, err := vk.DispatchMultiMarked(r.d[i:j], true)
		if err != nil {
			return nil, nil, 0, fmt.Errorf("llm: dispatches %d-%d: %w", i, j-1, err)
		}
		if batchTimes {
			fmt.Fprintf(os.Stderr, "batch %d-%d: %v on the GPU\n", i, j-1, el)
		}
		total += el
		if each == nil {
			// The shim refused the marks, which at this size it cannot; the
			// pass still ran, so report it as one block rather than losing it.
			byOwner[r.owner[i]] += el
			s := byKind[r.kind[i]]
			s.Count, s.GPU = s.Count+j-i, s.GPU+el
			byKind[r.kind[i]] = s
			continue
		}
		for k, d := range each {
			byOwner[r.owner[i+k]] += d
			s := byKind[r.kind[i+k]]
			s.Count, s.GPU = s.Count+1, s.GPU+d
			byKind[r.kind[i+k]] = s
		}
	}
	r.d, r.owner, r.kind = r.d[:0], r.owner[:0], r.kind[:0]
	return byOwner, byKind, total, nil
}

// dumpRange prints the block and grid of a slice of the recorded sequence
// before it is submitted, which is the only moment a dispatch that hangs the
// GPU can still be named. LLM_DISPATCH_DUMP=lo:hi selects the range; the
// dispatch a pass stopped at is the one after the last timestamp slot that
// came back (slot k is written after dispatch k-1).
func (r *recorder) dumpRange() {
	spec := os.Getenv("LLM_DISPATCH_DUMP")
	if spec == "" {
		return
	}
	lo, hi := 0, len(r.d)
	if a, b, ok := strings.Cut(spec, ":"); ok {
		if v, err := strconv.Atoi(a); err == nil {
			lo = v
		}
		if v, err := strconv.Atoi(b); err == nil {
			hi = v
		}
	}
	lo, hi = max(lo, 0), minInt(hi, len(r.d))
	fmt.Fprintf(os.Stderr, "dispatch dump: %d recorded, showing %d-%d\n", len(r.d), lo, hi-1)
	for i := lo; i < hi; i++ {
		fmt.Fprintf(os.Stderr, "  %4d %-5s groups %dx%d pc %d\n",
			i, r.owner[i], r.d[i].GroupsX, r.d[i].GroupsY, len(r.d[i].PushConstants))
	}
}

// Package vk is a minimal Go wrapper around shim.c/shim.h, which does the
// actual Vulkan calls. See shim.h for why the struct-building work lives in
// C rather than here.
package vk

/*
#cgo pkg-config: vulkan
#include "shim.h"
#include <stdlib.h>
*/
import "C"

import (
	"fmt"
	"strings"
	"time"
	"unsafe"
)

// Error wraps a non-VK_SUCCESS VkResult.
type Error struct {
	Op     string
	Result C.VkResult
}

func (e *Error) Error() string {
	return fmt.Sprintf("vk: %s failed: VkResult(%d)", e.Op, int32(e.Result))
}

func check(op string, r C.VkResult) error {
	if r != C.VK_SUCCESS {
		return &Error{Op: op, Result: r}
	}
	return nil
}

func boolToVk(b bool) C.VkBool32 {
	if b {
		return C.VK_TRUE
	}
	return C.VK_FALSE
}

// Instance wraps a VkInstance.
type Instance struct {
	handle C.VkInstance
}

// NewInstance creates a VkInstance with no extensions or layers — enough for
// headless compute. appName is purely informational (shows up in tools like
// validation layers or GPU profilers).
func NewInstance(appName string) (*Instance, error) {
	cAppName := C.CString(appName)
	defer C.free(unsafe.Pointer(cAppName))

	var handle C.VkInstance
	if err := check("vkCreateInstance", C.shim_create_instance(cAppName, &handle)); err != nil {
		return nil, err
	}
	return &Instance{handle: handle}, nil
}

// Destroy releases the instance.
func (i *Instance) Destroy() {
	C.shim_destroy_instance(i.handle)
}

// DeviceFeatures are the optional compute-relevant device features this
// benchmark suite cares about: fp16 math/storage, int8 storage, accelerated
// integer dot-product instructions, and cooperative-matrix (matrix-multiply
// acceleration).
type DeviceFeatures struct {
	Float16           bool
	Int8              bool
	IntegerDotProduct bool
	CoopMatrix        bool
	// SubgroupSizeControl enables VK_EXT_subgroup_size_control, without which
	// PipelineSpec.RequiredSubgroupSize must stay 0 and every shader runs at
	// whatever wave size the driver picks (IDEAS.md §6.2).
	SubgroupSizeControl bool
}

func (f DeviceFeatures) toShim() C.ShimDeviceFeatures {
	return C.ShimDeviceFeatures{
		float16:             boolToVk(f.Float16),
		int8:                boolToVk(f.Int8),
		integerDotProduct:   boolToVk(f.IntegerDotProduct),
		coopMatrix:          boolToVk(f.CoopMatrix),
		subgroupSizeControl: boolToVk(f.SubgroupSizeControl),
	}
}

// SubgroupSizeControl is what wave sizes a compute pipeline on this device
// may require. Supported folds together the extension's presence, the
// feature bit and whether the compute stage accepts a required size, because
// a pipeline may only name one when all three hold.
type SubgroupSizeControl struct {
	Supported                    bool
	ComputeFullSubgroups         bool
	MinSubgroupSize              uint32
	MaxSubgroupSize              uint32
	MaxComputeWorkgroupSubgroups uint32
}

// ComponentType mirrors VkComponentTypeKHR — the element type of a
// cooperative-matrix operand.
type ComponentType uint32

const (
	ComponentFloat16 ComponentType = 0
	ComponentFloat32 ComponentType = 1
	ComponentFloat64 ComponentType = 2
	ComponentSInt8   ComponentType = 3
	ComponentSInt16  ComponentType = 4
	ComponentSInt32  ComponentType = 5
	ComponentSInt64  ComponentType = 6
	ComponentUInt8   ComponentType = 7
	ComponentUInt16  ComponentType = 8
	ComponentUInt32  ComponentType = 9
	ComponentUInt64  ComponentType = 10
)

// Scope mirrors VkScopeKHR — which set of invocations cooperate on a
// cooperative-matrix operation.
type Scope uint32

const (
	ScopeDevice      Scope = 1
	ScopeWorkgroup   Scope = 2
	ScopeSubgroup    Scope = 3
	ScopeQueueFamily Scope = 5
)

// CoopMatShape is one MxNxK/type/scope combination VK_KHR_cooperative_matrix
// supports on a given device.
type CoopMatShape struct {
	M, N, K                         int
	AType, BType, CType, ResultType ComponentType
	Scope                           Scope
}

// PhysicalDevice wraps a VkPhysicalDevice plus its cached properties.
type PhysicalDevice struct {
	handle          C.VkPhysicalDevice
	instance        C.VkInstance
	Name            string
	VendorID        uint32
	DeviceID        uint32
	DeviceType      C.VkPhysicalDeviceType
	TimestampPeriod float64 // nanoseconds per timestamp-query tick
}

const maxPhysicalDevices = 64

// PhysicalDevices enumerates every physical device the instance can see.
func (i *Instance) PhysicalDevices() ([]PhysicalDevice, error) {
	raw := make([]C.ShimPhysicalDevice, maxPhysicalDevices)
	var count C.uint32_t
	if err := check("vkEnumeratePhysicalDevices",
		C.shim_enumerate_physical_devices(i.handle, &raw[0], C.uint32_t(len(raw)), &count)); err != nil {
		return nil, err
	}
	if count == 0 {
		return nil, fmt.Errorf("vk: no physical devices found")
	}

	devices := make([]PhysicalDevice, 0, count)
	for _, d := range raw[:count] {
		devices = append(devices, PhysicalDevice{
			handle:          d.handle,
			instance:        i.handle,
			Name:            C.GoString(&d.name[0]),
			VendorID:        uint32(d.vendorID),
			DeviceID:        uint32(d.deviceID),
			DeviceType:      d.deviceType,
			TimestampPeriod: float64(d.timestampPeriod),
		})
	}
	return devices, nil
}

// ComputeQueueFamily returns the index of the first queue family on this
// device that supports compute.
func (p *PhysicalDevice) ComputeQueueFamily() (uint32, error) {
	var family C.uint32_t
	if err := check("vkGetPhysicalDeviceQueueFamilyProperties",
		C.shim_find_compute_queue_family(p.handle, &family)); err != nil {
		return 0, fmt.Errorf("vk: device %s has no compute-capable queue family", p.Name)
	}
	return uint32(family), nil
}

// SupportedFeatures reports which optional DeviceFeatures this physical
// device actually supports, independent of what any logical device enables.
func (p *PhysicalDevice) SupportedFeatures() (DeviceFeatures, error) {
	var out C.ShimDeviceFeatures
	if err := check("vkGetPhysicalDeviceFeatures2", C.shim_query_device_features(p.handle, &out)); err != nil {
		return DeviceFeatures{}, err
	}
	return DeviceFeatures{
		Float16:             out.float16 != 0,
		Int8:                out.int8 != 0,
		IntegerDotProduct:   out.integerDotProduct != 0,
		CoopMatrix:          out.coopMatrix != 0,
		SubgroupSizeControl: out.subgroupSizeControl != 0,
	}, nil
}

// SubgroupSizeControl reports the wave sizes this device will let a compute
// pipeline pin itself to. Supported == false means the default wave size is
// all there is.
func (p *PhysicalDevice) SubgroupSizeControl() (SubgroupSizeControl, error) {
	var out C.ShimSubgroupSizeControl
	if err := check("vkGetPhysicalDeviceProperties2", C.shim_query_subgroup_size_control(p.handle, &out)); err != nil {
		return SubgroupSizeControl{}, err
	}
	return SubgroupSizeControl{
		Supported:                    out.supported != 0,
		ComputeFullSubgroups:         out.computeFullSubgroups != 0,
		MinSubgroupSize:              uint32(out.minSubgroupSize),
		MaxSubgroupSize:              uint32(out.maxSubgroupSize),
		MaxComputeWorkgroupSubgroups: uint32(out.maxComputeWorkgroupSubgroups),
	}, nil
}

const maxCoopMatShapes = 64

// CooperativeMatrixShapes enumerates the MxNxK/type/scope combinations
// VK_KHR_cooperative_matrix supports on this device. Returns an empty slice
// (not an error) if the extension isn't supported — check SupportedFeatures
// first.
func (p *PhysicalDevice) CooperativeMatrixShapes() ([]CoopMatShape, error) {
	raw := make([]C.ShimCoopMatProperty, maxCoopMatShapes)
	var count C.uint32_t
	if err := check("vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR",
		C.shim_query_cooperative_matrix_properties(p.instance, p.handle, &raw[0], C.uint32_t(len(raw)), &count)); err != nil {
		return nil, err
	}

	shapes := make([]CoopMatShape, 0, count)
	for _, s := range raw[:count] {
		shapes = append(shapes, CoopMatShape{
			M: int(s.MSize), N: int(s.NSize), K: int(s.KSize),
			AType:      ComponentType(s.AType),
			BType:      ComponentType(s.BType),
			CType:      ComponentType(s.CType),
			ResultType: ComponentType(s.ResultType),
			Scope:      Scope(s.scope),
		})
	}
	return shapes, nil
}

// Device wraps a VkDevice and the single compute queue we pulled from it.
type Device struct {
	handle      C.VkDevice
	phys        *PhysicalDevice
	queue       C.VkQueue
	queueFamily uint32
	features    DeviceFeatures
}

// NewDevice creates a logical device on phys with a single queue drawn from
// queueFamily, enabling exactly the optional features set in the request.
func NewDevice(phys *PhysicalDevice, queueFamily uint32, features DeviceFeatures) (*Device, error) {
	req := features.toShim()
	var handle C.VkDevice
	var queue C.VkQueue
	if err := check("vkCreateDevice",
		C.shim_create_device(phys.handle, C.uint32_t(queueFamily), &req, &handle, &queue)); err != nil {
		return nil, err
	}
	return &Device{handle: handle, phys: phys, queue: queue, queueFamily: queueFamily, features: features}, nil
}

// Physical returns the physical device this logical device was created on, so
// a caller holding only the Device can still ask what the hardware reports —
// cooperative-matrix shapes, for instance.
func (d *Device) Physical() *PhysicalDevice { return d.phys }

// Features returns the optional features this device was *created* with,
// which is what a shader may actually use: a feature the hardware supports
// but NewDevice was not asked for is not enabled.
func (d *Device) Features() DeviceFeatures { return d.features }

// Destroy releases the device.
func (d *Device) Destroy() {
	C.shim_destroy_device(d.handle)
}

// Handle returns the raw VkDevice.
func (d *Device) Handle() C.VkDevice { return d.handle }

// Queue returns the VkQueue pulled from the device's queue family.
func (d *Device) Queue() C.VkQueue { return d.queue }

// QueueFamily returns the index of the queue family backing Queue().
func (d *Device) QueueFamily() uint32 { return d.queueFamily }

// WaitIdle blocks until every queue on the device is idle.
func (d *Device) WaitIdle() error {
	return check("vkDeviceWaitIdle", C.shim_device_wait_idle(d.handle))
}

// Buffer is a VkBuffer bound to host-visible memory (device-local when the
// hardware supports it — see shim_create_storage_buffer), mapped for the
// lifetime of the buffer.
type Buffer struct {
	dev    *Device
	handle C.VkBuffer
	memory C.VkDeviceMemory
	mapped unsafe.Pointer
	size   int
}

// Memory property bits, as reported per memory type. Named here rather than
// imported from cgo so a caller can test them without the C types.
const (
	MemoryDeviceLocal    = 0x0001
	MemoryHostVisible    = 0x0002
	MemoryHostCoherent   = 0x0004
	MemoryHostCached     = 0x0008
	MemoryDeviceCoherent = 0x0040 // VK_AMD_device_coherent_memory
	MemoryDeviceUncached = 0x0080 // VK_AMD_device_coherent_memory
)

// MemoryType is one entry of the device's memory-type table, with the heap it
// draws from. This device exposes eleven of them across two heaps that overlap
// the same physical RAM, and which one a weight bank lands in decides both how
// large it may be (heap 1 stops at 83.79 GiB) and, possibly, how fast it
// reads — IDEAS §5.1, LLM.md L0b.
type MemoryType struct {
	Index            uint32
	HeapIndex        uint32
	Flags            uint32
	HeapSize         uint64
	BufferCompatible bool // can back a plain storage buffer
}

// Has reports whether every bit in want is set.
func (m MemoryType) Has(want uint32) bool { return m.Flags&want == want }

// String renders the property bits the way vulkaninfo names them, shortened.
func (m MemoryType) String() string {
	names := []struct {
		bit  uint32
		name string
	}{
		{MemoryDeviceLocal, "DEVICE_LOCAL"},
		{MemoryHostVisible, "HOST_VISIBLE"},
		{MemoryHostCoherent, "HOST_COHERENT"},
		{MemoryHostCached, "HOST_CACHED"},
		{MemoryDeviceCoherent, "DEVICE_COHERENT"},
		{MemoryDeviceUncached, "DEVICE_UNCACHED"},
	}
	var parts []string
	for _, n := range names {
		if m.Flags&n.bit != 0 {
			parts = append(parts, n.name)
		}
	}
	if len(parts) == 0 {
		return "-"
	}
	return strings.Join(parts, "|")
}

// MemoryTypes returns the device's memory-type table.
func (d *Device) MemoryTypes() ([]MemoryType, error) {
	const max = 32
	raw := make([]C.ShimMemoryType, max)
	var count C.uint32_t
	if err := check("vkGetPhysicalDeviceMemoryProperties",
		C.shim_memory_types(d.handle, d.phys.handle, &raw[0], C.uint32_t(max), &count)); err != nil {
		return nil, err
	}
	n := int(count)
	if n > max {
		n = max
	}
	out := make([]MemoryType, n)
	for i := 0; i < n; i++ {
		out[i] = MemoryType{
			Index:            uint32(raw[i].index),
			HeapIndex:        uint32(raw[i].heapIndex),
			Flags:            uint32(raw[i].propertyFlags),
			HeapSize:         uint64(raw[i].heapSize),
			BufferCompatible: raw[i].bufferCompatible != 0,
		}
	}
	return out, nil
}

// NewHostCachedBuffer allocates a storage buffer from a HOST_CACHED memory
// type when the device has one, and falls back to NewBuffer when it does not.
//
// It exists for **activation arenas the host reads back**, and the difference
// is not marginal. On this device the type NewBuffer prefers —
// DEVICE_LOCAL|HOST_VISIBLE|HOST_COHERENT, write-combined — is written at
// 50 GB/s and read at **0.18**, because an uncached mapping turns a read into
// one uncached load per cache line. A HOST_CACHED type reads the same buffer
// at **24.8 GB/s**, 138x, and writes it at 70. See LLM.md L6b.
//
// It is not the right choice for a weight bank: those are written once and
// never read, so the cached type buys only its faster write, and the GPU-side
// rate is what a bank is about (L0b: every type reads at 236-237 GB/s from
// the device, so the choice is free there and it is not free here).
func (d *Device) NewHostCachedBuffer(size int) (*Buffer, error) {
	types, err := d.MemoryTypes()
	if err != nil {
		return nil, err
	}
	const want = MemoryHostVisible | MemoryHostCoherent | MemoryHostCached
	for _, mt := range types {
		if mt.BufferCompatible && mt.Has(want) {
			return d.NewBufferOfType(size, mt.Index)
		}
	}
	return d.NewBuffer(size)
}

// NewBufferOfType allocates a storage buffer from a named memory type rather
// than from the one NewBuffer prefers. A type without HOST_VISIBLE cannot be
// mapped, so MappedPointer and every Write/Read method on the result are
// unusable — such a buffer is only good for a kernel that reads whatever the
// allocation happened to contain, which is exactly what the bandwidth probes
// want.
func (d *Device) NewBufferOfType(size int, memType uint32) (*Buffer, error) {
	var handle C.VkBuffer
	var memory C.VkDeviceMemory
	var mapped unsafe.Pointer
	if err := check("vkCreateBuffer/vkAllocateMemory",
		C.shim_create_storage_buffer_of_type(d.handle, C.VkDeviceSize(size), C.uint32_t(memType),
			&handle, &memory, &mapped)); err != nil {
		return nil, err
	}
	return &Buffer{dev: d, handle: handle, memory: memory, mapped: mapped, size: size}, nil
}

// Mapped reports whether the buffer's memory could be mapped, which is false
// only for a NewBufferOfType on a type without HOST_VISIBLE.
func (b *Buffer) Mapped() bool { return b.mapped != nil }

// NewBuffer allocates a buffer of size bytes usable as a storage buffer in a
// compute shader, left mapped.
func (d *Device) NewBuffer(size int) (*Buffer, error) {
	var handle C.VkBuffer
	var memory C.VkDeviceMemory
	var mapped unsafe.Pointer
	if err := check("vkCreateBuffer/vkAllocateMemory",
		C.shim_create_storage_buffer(d.handle, d.phys.handle, C.VkDeviceSize(size), &handle, &memory, &mapped)); err != nil {
		return nil, err
	}
	return &Buffer{dev: d, handle: handle, memory: memory, mapped: mapped, size: size}, nil
}

// Destroy unmaps and releases the buffer's memory and handle.
func (b *Buffer) Destroy() {
	C.shim_destroy_buffer(b.dev.handle, b.handle, b.memory)
}

// Size returns the buffer's size in bytes.
func (b *Buffer) Size() int { return b.size }

// WriteFloat32 copies src into the buffer's mapped memory starting at byte 0.
func (b *Buffer) WriteFloat32(src []float32) {
	dst := unsafe.Slice((*float32)(b.mapped), len(src))
	copy(dst, src)
}

// ReadFloat32 reads n float32s back out of the buffer's mapped memory.
func (b *Buffer) ReadFloat32(n int) []float32 {
	src := unsafe.Slice((*float32)(b.mapped), n)
	out := make([]float32, n)
	copy(out, src)
	return out
}

// WriteFloat32At copies src into the buffer's mapped memory at an element
// offset, so several tensors can share one arena.
func (b *Buffer) WriteFloat32At(off int, src []float32) {
	dst := unsafe.Slice((*float32)(b.mapped), off+len(src))
	copy(dst[off:], src)
}

// ReadFloat32At reads n float32s starting at an element offset. Reading a
// whole buffer to recover a tensor near its end is the difference between
// copying a few megabytes and copying gigabytes, which for the VAE decoder's
// activation arena was 23x the GPU time of the decode itself.
func (b *Buffer) ReadFloat32At(off, n int) []float32 {
	src := unsafe.Slice((*float32)(b.mapped), off+n)
	out := make([]float32, n)
	copy(out, src[off:])
	return out
}

// ZeroFloat32At clears n float32s at an element offset, in place in the
// mapped memory.
//
// It exists because `WriteFloat32At(off, make([]float32, n))` is two costs,
// and on a hot path the allocation is the larger one: the gated DeltaNet's
// recurrent state is 3.1 MB a layer and 36 layers of it are reset at the
// start of every prefill, so the obvious spelling was **113 MB of Go
// allocation a graph** — a fixed ~55 ms whatever the prompt length, which is
// 12% of a 128-token pass and invisible at 2048 (LLM.md L6c-3).
func (b *Buffer) ZeroFloat32At(off, n int) {
	clear(unsafe.Slice((*float32)(b.mapped), off+n)[off:])
}

// ZeroUint16At clears n uint16s at an element offset, for the fp16 arenas.
func (b *Buffer) ZeroUint16At(off, n int) {
	clear(unsafe.Slice((*uint16)(b.mapped), off+n)[off:])
}

// Zero clears the whole buffer, which is what an arena wants once at
// allocation: the pad columns of every A operand and the pad rows of a short
// run come from here, and the kernels have no bounds checks.
func (b *Buffer) Zero() {
	clear(unsafe.Slice((*byte)(b.mapped), b.size))
}

// WriteUint16At copies src into the buffer's mapped memory at a uint16
// element offset. fp16 is the matrix cores' only operand type, so a weight
// arena is filled through this rather than WriteFloat32At; the caller does
// the narrowing, because the layout it writes into is usually a transpose or
// a retiling of the tensor it came from.
func (b *Buffer) WriteUint16At(off int, src []uint16) {
	dst := unsafe.Slice((*uint16)(b.mapped), off+len(src))
	copy(dst[off:], src)
}

// ReadUint16At reads n uint16s starting at a uint16 element offset.
func (b *Buffer) ReadUint16At(off, n int) []uint16 {
	src := unsafe.Slice((*uint16)(b.mapped), off+n)
	out := make([]uint16, n)
	copy(out, src[off:])
	return out
}

// ReadUint32At reads n uint32s starting at a uint32 element offset. Storage
// buffers that hold bit-packed data rather than numbers — a mask, an index
// list — are read through this instead of ReadFloat32At, so that nothing goes
// through a float on the way.
func (b *Buffer) ReadUint32At(off, n int) []uint32 {
	src := unsafe.Slice((*uint32)(b.mapped), off+n)
	out := make([]uint32, n)
	copy(out, src[off:])
	return out
}

// ReadUint32 reads n uint32s back out of the buffer's mapped memory.
func (b *Buffer) ReadUint32(n int) []uint32 {
	src := unsafe.Slice((*uint32)(b.mapped), n)
	out := make([]uint32, n)
	copy(out, src)
	return out
}

// MappedPointer returns the start of the buffer's host mapping, for callers
// that want to fill or read it as a type the Write*/Read* helpers don't
// cover, or to fill a multi-hundred-MB buffer in place rather than building
// a host-side copy of it first.
func (b *Buffer) MappedPointer() unsafe.Pointer { return b.mapped }

// WriteBytes copies src into the buffer's mapped memory starting at byte 0.
func (b *Buffer) WriteBytes(src []byte) {
	dst := unsafe.Slice((*byte)(b.mapped), len(src))
	copy(dst, src)
}

// WriteBytesAt copies src into the buffer's mapped memory at a byte offset.
// A quantised weight bank is staged through this rather than through
// WriteFloat32At: its blocks are 24, 34, 144 or 176 bytes and nothing about
// them is a float, so the host copies the checkpoint's own bytes and the
// shader unpacks them (LLM.md L5b).
func (b *Buffer) WriteBytesAt(off int, src []byte) {
	dst := unsafe.Slice((*byte)(b.mapped), off+len(src))
	copy(dst[off:], src)
}

// FillRepeating tiles block across the whole buffer, in place. It exists for
// the multi-gigabyte weight banks IDEAS §3.5 needs: a 512-expert fp16 bank is
// 1.8 GB, and building a host-side copy of that to hand to WriteBytes costs
// more than the measurement it feeds. Only the addresses matter for a timing
// run, so a repeating block of real values is as good as a unique one — and
// it must be real values, because reinterpreting whatever the allocation held
// as fp16 can produce infinities that change what the arithmetic costs.
func (b *Buffer) FillRepeating(block []byte) {
	if len(block) == 0 {
		return
	}
	dst := unsafe.Slice((*byte)(b.mapped), b.size)
	for off := 0; off < len(dst); off += len(block) {
		copy(dst[off:], block)
	}
}

// ReadBytes reads n bytes back out of the buffer's mapped memory.
func (b *Buffer) ReadBytes(n int) []byte {
	src := unsafe.Slice((*byte)(b.mapped), n)
	out := make([]byte, n)
	copy(out, src)
	return out
}

// Handle returns the raw VkBuffer.
func (b *Buffer) Handle() C.VkBuffer { return b.handle }

// ShaderModule wraps a VkShaderModule.
type ShaderModule struct {
	dev    *Device
	handle C.VkShaderModule
}

// NewShaderModule loads pre-compiled SPIR-V bytecode.
func (d *Device) NewShaderModule(spirv []byte) (*ShaderModule, error) {
	if len(spirv)%4 != 0 {
		return nil, fmt.Errorf("vk: SPIR-V length %d is not a multiple of 4", len(spirv))
	}
	var handle C.VkShaderModule
	if err := check("vkCreateShaderModule",
		C.shim_create_shader_module(d.handle, unsafe.Pointer(&spirv[0]), C.size_t(len(spirv)), &handle)); err != nil {
		return nil, err
	}
	return &ShaderModule{dev: d, handle: handle}, nil
}

// Destroy releases the shader module.
func (s *ShaderModule) Destroy() {
	C.shim_destroy_shader_module(s.dev.handle, s.handle)
}

// Handle returns the raw VkShaderModule.
func (s *ShaderModule) Handle() C.VkShaderModule { return s.handle }

// SpecConstant is one uint32 specialization constant, identified by the
// constant ID it's declared with in GLSL (`layout(constant_id = ID)`).
type SpecConstant struct {
	ID    uint32
	Value uint32
}

// PipelineSpec describes the resources a ComputePipeline binds: one storage
// buffer per entry in Buffers (bound to bindings 0..len(Buffers)-1), an
// optional push-constant range, and optional specialization constants.
type PipelineSpec struct {
	Buffers []*Buffer
	// Counts, when set, groups Buffers into descriptor *arrays*: binding i
	// holds Counts[i] consecutive buffers, and the shader declares it as
	// `buffer B { ... } b[N]` and indexes it with a dynamically uniform
	// expression. Its sum must be len(Buffers). Nil is the plain
	// arrangement — one buffer per binding, in order — which is what every
	// kernel here but one uses.
	//
	// It exists because `maxStorageBufferRange` on this device is 4 GiB - 4
	// and the MoE bank is 77 GB (LLM.md L6a): the bank is one buffer a layer,
	// bound as one array, and the layer index selects.
	Counts           []uint32
	PushConstantSize uint32
	SpecConstants    []SpecConstant
	// RequiredSubgroupSize pins the wave size the shader runs at instead of
	// letting the driver choose (IDEAS.md §6.2). Zero keeps the default. It
	// must be a power of two inside the device's reported
	// [MinSubgroupSize, MaxSubgroupSize], the shader's local_size_x must be a
	// multiple of it, and the device must have been created with
	// DeviceFeatures.SubgroupSizeControl — otherwise pipeline creation fails.
	RequiredSubgroupSize uint32
}

// ComputePipeline is a full pipeline (descriptor set layout, pipeline,
// descriptor set, command buffer, fence and timestamp query pool) built
// from a PipelineSpec.
type ComputePipeline struct {
	dev    *Device
	handle C.ShimComputePipeline
}

// NewPipeline builds a compute pipeline for shader bound according to spec.
func (d *Device) NewPipeline(shader *ShaderModule, spec PipelineSpec) (*ComputePipeline, error) {
	p := &ComputePipeline{dev: d}

	bufHandles := make([]C.VkBuffer, len(spec.Buffers))
	for i, b := range spec.Buffers {
		bufHandles[i] = b.handle
	}
	var bufPtr *C.VkBuffer
	if len(bufHandles) > 0 {
		bufPtr = &bufHandles[0]
	}

	var countPtr *C.uint32_t
	var counts []C.uint32_t
	if len(spec.Counts) > 0 {
		total := 0
		for _, n := range spec.Counts {
			total += int(n)
		}
		if total != len(spec.Buffers) {
			return nil, fmt.Errorf("vk: PipelineSpec.Counts sums to %d, but there are %d buffers", total, len(spec.Buffers))
		}
		counts = make([]C.uint32_t, len(spec.Counts))
		for i, n := range spec.Counts {
			counts[i] = C.uint32_t(n)
		}
		countPtr = &counts[0]
	}

	var specC []C.ShimSpecConstant
	if len(spec.SpecConstants) > 0 {
		specC = make([]C.ShimSpecConstant, len(spec.SpecConstants))
		for i, sc := range spec.SpecConstants {
			specC[i] = C.ShimSpecConstant{constantID: C.uint32_t(sc.ID), value: C.uint32_t(sc.Value)}
		}
	}
	var specPtr *C.ShimSpecConstant
	if len(specC) > 0 {
		specPtr = &specC[0]
	}

	if err := check("vkCreateComputePipelines",
		C.shim_create_compute_pipeline(d.handle, shader.handle, bufPtr, C.uint32_t(len(bufHandles)),
			countPtr, C.uint32_t(len(spec.Counts)),
			C.uint32_t(spec.PushConstantSize), specPtr, C.uint32_t(len(specC)),
			C.uint32_t(spec.RequiredSubgroupSize),
			C.uint32_t(d.queueFamily), &p.handle)); err != nil {
		p.Destroy()
		return nil, err
	}
	return p, nil
}

// NewComputePipeline is a convenience wrapper for the common case of a
// single storage-buffer binding and no push constants or specialization
// constants.
func (d *Device) NewComputePipeline(shader *ShaderModule, buf *Buffer) (*ComputePipeline, error) {
	return d.NewPipeline(shader, PipelineSpec{Buffers: []*Buffer{buf}})
}

// DispatchTimed records iterations back-to-back dispatches of
// (groupsX,groupsY,groupsZ) workgroups (with a barrier between each, so
// in-place steady-state throughput is what gets measured), submits them,
// blocks until complete, and returns the GPU-side elapsed time measured via
// timestamp queries — not wall-clock time, so it excludes CPU submission and
// scheduling overhead.
func (p *ComputePipeline) DispatchTimed(groupsX, groupsY, groupsZ, iterations uint32, pushConstants []byte) (time.Duration, error) {
	var start, end C.uint64_t
	var pcPtr unsafe.Pointer
	var pcLen C.uint32_t
	if len(pushConstants) > 0 {
		pcPtr = unsafe.Pointer(&pushConstants[0])
		pcLen = C.uint32_t(len(pushConstants))
	}
	if err := check("vkQueueSubmit", C.shim_dispatch_timed(p.dev.handle, p.dev.queue, &p.handle,
		C.uint32_t(groupsX), C.uint32_t(groupsY), C.uint32_t(groupsZ), C.uint32_t(iterations),
		pcPtr, pcLen, &start, &end)); err != nil {
		return 0, err
	}
	ticks := float64(uint64(end)) - float64(uint64(start))
	ns := ticks * p.dev.phys.TimestampPeriod
	return time.Duration(ns), nil
}

// DispatchSequenceTimed is DispatchTimed for a sequence of dispatches that
// differ in their push constants: the i-th covers groupsX[i] workgroups on
// the X axis and pushes pushConstants[i], and a barrier separates every
// dispatch from the next — within one iteration and across iterations alike.
//
// It exists for IDEAS §3.5's baseline. A grouped kernel's claim is that one
// dispatch over a tile table beats one dispatch per expert, and the losing
// arm of that comparison is a sequence of 512 dispatches whose only
// difference is where in the table each starts. Expressing that with
// DispatchTimed is impossible (one constant block per command buffer), and
// expressing it as 512 separate submits would measure the CPU's submit path
// instead of the GPU's.
//
// Every element of pushConstants must be the same length, since the pipeline
// layout declares one range.
func (p *ComputePipeline) DispatchSequenceTimed(groupsX []uint32, groupsY, groupsZ, iterations uint32, pushConstants [][]byte) (time.Duration, error) {
	if len(groupsX) == 0 {
		return 0, fmt.Errorf("DispatchSequenceTimed: empty dispatch sequence")
	}
	if len(pushConstants) != 0 && len(pushConstants) != len(groupsX) {
		return 0, fmt.Errorf("DispatchSequenceTimed: %d push-constant blocks for %d dispatches",
			len(pushConstants), len(groupsX))
	}
	// Flattened into one contiguous buffer because cgo will not let a Go
	// slice of Go slices cross the boundary.
	var flat []byte
	var pcSize int
	if len(pushConstants) > 0 {
		pcSize = len(pushConstants[0])
		flat = make([]byte, 0, pcSize*len(pushConstants))
		for i, b := range pushConstants {
			if len(b) != pcSize {
				return 0, fmt.Errorf("DispatchSequenceTimed: push-constant block %d is %d bytes, block 0 is %d",
					i, len(b), pcSize)
			}
			flat = append(flat, b...)
		}
	}

	var start, end C.uint64_t
	var pcPtr unsafe.Pointer
	if len(flat) > 0 {
		pcPtr = unsafe.Pointer(&flat[0])
	}
	if err := check("vkQueueSubmit", C.shim_dispatch_seq_timed(p.dev.handle, p.dev.queue, &p.handle,
		(*C.uint32_t)(unsafe.Pointer(&groupsX[0])), C.uint32_t(len(groupsX)),
		C.uint32_t(groupsY), C.uint32_t(groupsZ), C.uint32_t(iterations),
		pcPtr, C.uint32_t(pcSize), &start, &end)); err != nil {
		return 0, err
	}
	ticks := float64(uint64(end)) - float64(uint64(start))
	return time.Duration(ticks * p.dev.phys.TimestampPeriod), nil
}

// MultiDispatch is one dispatch of a mixed-pipeline sequence: which pipeline
// runs, over what grid, with which push constants.
type MultiDispatch struct {
	Pipeline      *ComputePipeline
	GroupsX       uint32
	GroupsY       uint32
	PushConstants []byte
}

// DispatchMultiTimed is DispatchSequenceTimed for a sequence whose dispatches
// use *different pipelines* and *different grid extents*.
//
// It exists for the mixed-width MoE decode dispatch (IDEAS §1.12). The M block
// a grouped GEMV carries is compiled in, so covering a routing histogram with
// several widths at once is one dispatch per width, each binding the build for
// that width and naming its own contiguous slice of the shared slot table. The
// dispatches write disjoint output rows, so `barriers` is a knob rather than a
// requirement: false lets the widths overlap the way an engine would let them,
// true charges the split a compute->compute barrier between every pair, which
// is what it costs if the overlap cannot be had.
//
// Every pipeline must have been built over the same buffers and the same
// push-constant size — the recording uses the first one's command buffer,
// query pool and fence — and every push-constant block must be the same
// length, since each pipeline layout declares one range.
func DispatchMultiTimed(dispatches []MultiDispatch, groupsZ, iterations uint32, barriers bool) (time.Duration, error) {
	d, _, err := dispatchMulti(dispatches, groupsZ, iterations, barriers, false)
	return d, err
}

// DispatchMultiMarked records the same sequence and returns **one duration per
// dispatch** as well as the total, by writing a timestamp after each rather
// than only at the two ends.
//
// It is what makes one command buffer a *token* affordable to reason about
// (LLM.md L7d). A submit and a fence wait is ~40 us on this device and a
// decode step was ~490 of them, one a block — so merging them is worth about
// 15% — but the per-block wall clock the engine has been tuned by lives in
// exactly those boundaries. This moves the attribution inside the command
// buffer, where it is GPU time rather than host time and so is strictly the
// better number: it is what GGML_VK_PERF_LOGGER reports for llama.cpp's own
// graph, on our side of the comparison.
//
// One pass only, and at most SHIM_QUERY_SLOTS-1 dispatches; past either it
// falls back to the total, and the per-dispatch slice comes back nil.
func DispatchMultiMarked(dispatches []MultiDispatch, barriers bool) (time.Duration, []time.Duration, error) {
	return dispatchMulti(dispatches, 1, 1, barriers, true)
}

func dispatchMulti(dispatches []MultiDispatch, groupsZ, iterations uint32, barriers, marks bool) (time.Duration, []time.Duration, error) {
	if len(dispatches) == 0 {
		return 0, nil, fmt.Errorf("DispatchMultiTimed: empty dispatch sequence")
	}
	dev := dispatches[0].Pipeline.dev
	// The pipelines are copied by value rather than referenced: a
	// ShimComputePipeline holds nothing but Vulkan handles, so a Go slice of
	// them carries no Go pointers and can cross the cgo boundary, which a
	// slice of *C.ShimComputePipeline could not.
	handles := make([]C.ShimComputePipeline, len(dispatches))
	groupsX := make([]C.uint32_t, len(dispatches))
	groupsY := make([]C.uint32_t, len(dispatches))
	var flat []byte
	pcSize := len(dispatches[0].PushConstants)
	for i, d := range dispatches {
		if d.Pipeline == nil {
			return 0, nil, fmt.Errorf("DispatchMultiTimed: dispatch %d has no pipeline", i)
		}
		if d.Pipeline.dev != dev {
			return 0, nil, fmt.Errorf("DispatchMultiTimed: dispatch %d is on a different device", i)
		}
		if len(d.PushConstants) != pcSize {
			return 0, nil, fmt.Errorf("DispatchMultiTimed: push-constant block %d is %d bytes, block 0 is %d",
				i, len(d.PushConstants), pcSize)
		}
		handles[i] = d.Pipeline.handle
		groupsX[i] = C.uint32_t(d.GroupsX)
		groupsY[i] = C.uint32_t(d.GroupsY)
		flat = append(flat, d.PushConstants...)
	}

	var start, end C.uint64_t
	var pcPtr unsafe.Pointer
	if len(flat) > 0 {
		pcPtr = unsafe.Pointer(&flat[0])
	}
	var barrierFlag C.uint32_t
	if barriers {
		barrierFlag = 1
	}
	var markBuf []C.uint64_t
	var markPtr *C.uint64_t
	if marks && len(dispatches)+1 <= int(C.SHIM_QUERY_SLOTS) {
		markBuf = make([]C.uint64_t, len(dispatches)+1)
		markPtr = &markBuf[0]
	}
	if err := check("dispatch sequence", C.shim_dispatch_multi_timed(dev.handle, dev.queue,
		&handles[0],
		&groupsX[0], &groupsY[0], C.uint32_t(len(dispatches)),
		C.uint32_t(groupsZ), C.uint32_t(iterations), barrierFlag,
		pcPtr, C.uint32_t(pcSize), &start, &end, markPtr)); err != nil {
		return 0, nil, err
	}
	ticks := float64(uint64(end)) - float64(uint64(start))
	total := time.Duration(ticks * dev.phys.TimestampPeriod)
	if markBuf == nil {
		return total, nil, nil
	}
	each := make([]time.Duration, len(dispatches))
	for i := range each {
		d := float64(uint64(markBuf[i+1])) - float64(uint64(markBuf[i]))
		each[i] = time.Duration(d * dev.phys.TimestampPeriod)
	}
	return total, each, nil
}

// Dispatch records and submits a single dispatch covering groupsX
// workgroups on the X axis, then blocks until it completes. Its GPU timing
// is discarded — use DispatchTimed for benchmarking.
func (p *ComputePipeline) Dispatch(groupsX uint32) error {
	_, err := p.DispatchTimed(groupsX, 1, 1, 1, nil)
	return err
}

// Destroy releases every object the pipeline owns.
func (p *ComputePipeline) Destroy() {
	C.shim_destroy_compute_pipeline(p.dev.handle, &p.handle)
}

package llm

// The graph (LLM.md L6b): the five blocks in llama.cpp's own order, over one
// resident model, from a token list to logits.
//
// L6a put every weight on the device — 84.20 GB in 68 buffers — but nothing
// had ever run two blocks in sequence. Each of them was built against the
// oracle in isolation: llama.cpp's own value for the tensor it reads went in,
// and its value for the tensor it writes came out. This file is where the
// inputs stop being the reference's and start being ours, which is the only
// way the thing that has been built since L2 is a model rather than five
// kernels.
//
// The order is `llama_model_qwen4exp::graph::graph`, and it is not the
// obvious one:
//
//	res = repeat(embed(ids), hc)            "hc_init"
//	for each layer:
//	    if it is the PLE layer: res += ple(res, ngram_embd)
//	    mixed, inject = hc_mix(res, attn)   the layer's *attention* mixer
//	    out = deltanet(mixed) | attention(mixed)
//	    res = hc_combine(res, out, inject)  "hc_combine-L"
//	    mixed, inject = hc_mix(res, ffn)
//	    out = moe(mixed)                    "ffn_out-L"
//	    res = hc_combine(res, out, inject)  "l_last-L"
//	norm = hc_mix(res[last], head)          "result_norm" -- there is no
//	logits = output * norm                  separate output norm
//
// Two things about that are worth saying out loud. The final mixer and the
// head run on **one row**: llama.cpp's `inp_out_ids` drops every token but
// the last before them, and the trace agrees — `result_output` is one row of
// 248320 floats for a seven-token prompt. And the residual never leaves the
// hyper-connection block's arena: `llm_hc_combine.comp` updates it in place,
// so what crosses a block boundary here is the 2560-wide `hc_mixed` going
// out and the 2560-wide block output coming back, not the 10240-wide stream.
//
// **The glue is a host round trip, and this is the first cut.** Every block
// owns its own arenas, so `hc_mixed` is read out of one fp32 arena, narrowed
// to halves and written into another — on this machine that is a memcpy
// between two mapped pointers of the same physical RAM, but it is a memcpy
// the reference does not do. L6b measures it rather than hiding it; fusing it
// away is a shared-arena change to five files and belongs to whatever comes
// after the number.

import (
	"fmt"
	"os"
	"runtime"
	"runtime/debug"
	"time"

	"strix-halo-vulkan/vk"
)

// GraphOpts are the choices that change what the graph allocates.
type GraphOpts struct {
	// MaxTokens is the longest prompt the arenas hold. Every block is sized
	// for it, and the MoE block's 0.87 GB of arenas scale with it.
	MaxTokens int
	// NKV is the attention cache's cell count. Zero takes the reference's
	// own rounding, MaxTokens up to 256 cells, which is what the 7-token
	// trace was dumped at.
	NKV int
	// Layers truncates the model to its first N layers. It is not a model —
	// the last mixer and the head still run — but it is how a graph gets
	// staged in seconds instead of 33 of them while the order is being
	// checked, and how a block's contribution is isolated by leaving the
	// ones after it out.
	Layers int
	// NoHead leaves `output.weight` unstaged, which saves 1.27 GB and 20
	// seconds for a caller that wants `result_norm` and not logits.
	NoHead bool
	// HeadRows is how many rows of logits the head's arena holds. One is
	// what the reference computes and what every caller before L8c wanted:
	// llama.cpp's graph ends with `inp_out_ids`, so prefill projects the
	// last token alone. A perplexity run wants every row, and a row is
	// 0.99 MB of f32 — 2.03 GB for a 2048-token chunk — so it names the
	// slab it works in here rather than asking for the batch.
	HeadRows int
	// DenseFP16 stages the dense weights as halves, which is what every
	// block did before L8. It is the control, not the default: the bank L8
	// stages is the checkpoint's own int8 with an fp16 scale per 32 elements,
	// which is half the bytes and — for a Q8_0 tensor — the same numbers
	// (bank.go). `LLM_DENSE_FP16=1` sets it from the environment, on the
	// precedent of L6b's `LLM_ARENA_UNCACHED`.
	DenseFP16 bool
}

// denseQ8 is whether the dense banks are L8's. The environment wins, so that
// a run can be repeated on the old bank without rebuilding a caller.
func (o GraphOpts) denseQ8() bool { return !o.DenseFP16 && DenseQ8() }

// DenseQ8 is that choice for a caller with no options of its own — the block
// benchmarks and `-resident`. L8's bank is the default and `LLM_DENSE_FP16=1`
// is the control, on the precedent of L6b's `LLM_ARENA_UNCACHED`.
//
// **A width simulation forces the fp16 arm** (sim.go). L8a's int8 bank is an
// identity only for a Q8_0 tensor, so staging a simulated Q4 weight through
// it would quantise twice and the number measured would be neither format's.
// The fp16 tiling holds the candidate's own halves exactly, which is the
// whole basis of the simulation, so it is the arm a sim has to use — at the
// cost of residency and tok/s being the fp16 arm's, which a sim cannot
// measure anyway.
func DenseQ8() bool { return os.Getenv("LLM_DENSE_FP16") != "1" && DensePlan().Off() }

// HCFuse is whether P1a's combine+norm fusion is in use: one dispatch per
// mixer boundary (`llm_hc_cn.comp`) instead of a scatter and a norm.
// `LLM_HC_NOFUSE=1` puts the pair back, which is the control the write-up's
// numbers are measured against and the arm
// TestHCFusionIsTheCombineThenTheNorm compares against.
//
// The two arms compute the **same bits**, which is what makes the control
// worth keeping: the combine is elementwise and the fused kernel keeps the
// norm's 256-thread partition and its 256-way tree, so nothing about the
// order of a sum changes. What changes is 94 dispatches a pass and one read
// of the wide residual per boundary.
func HCFuse() bool { return os.Getenv("LLM_HC_NOFUSE") != "1" }

// DecodeGEMV is whether the one-token kernels L8d added are in use: the MoE's
// expert GEMVs and split-K router, and the dense split-K GEMV under the gated
// DeltaNet's two projections. They are the default; `LLM_DECODE_GEMM=1` puts
// every one of them back on the cooperative-matrix GEMM that ran before L8d,
// which is the control the write-up's numbers are measured against — and the
// only way to run the two side by side over one prompt, since a block chooses
// its rung from the batch and not from a flag at the call site.
//
// The two paths do not compute the same numbers, and the difference is the
// order of a sum rather than the weights: a cooperative-matrix accumulator
// adds sixteen k an instruction in an order the extension does not define,
// where a GEMV lane adds them serially and a split-K reduce adds the slabs
// afterwards. It is f32 round-off over a 2560-long chain — rms 1.7e-05 on a
// projection whose scale is 31.5 — and at temperature zero over a hundred
// tokens it is enough to re-word a sentence. See L8d's gate.
func DecodeGEMV() bool { return os.Getenv("LLM_DECODE_GEMM") != "1" }

// blockKind says which sublayer a layer's attention half is, and where in its
// block's staged list it sits.
type blockKind struct {
	attn bool // false: gated DeltaNet
	idx  int
}

// Graph is the whole model on the device: the five blocks, the head, and the
// order that makes them one forward pass.
type Graph struct {
	m   *Model
	cfg Config

	hc   *HCGPU
	ple  *PLEGPU
	dn   *DeltaNetGPU
	attn *AttnGPU
	moe  *MoEGPU
	head *HeadGPU
	move *mover

	pleCfg PLEConfig
	hasPLE bool

	kinds  []blockKind
	nLayer int
	maxTok int
	nKV    int

	// The sequence, which is what L7 added. `past` is how many tokens of it
	// are already behind the graph — cells in the attention cache, positions
	// behind the PLE convolution, and tokens folded into every DeltaNet
	// layer's recurrent state — and `ids` is the whole of it, because the
	// n-gram gather is a trigram and a continuing run's first token still has
	// two predecessors.
	past int
	ids  []int32

	// Staged is what each block cost to put on the device, in the order they
	// were staged, for the caller that wants to print a plan.
	Staged []StagedBlock

	// Stats accumulates across every Prefill since ResetStats.
	Stats GraphStats

	// rec is the pass being recorded, installed on every block for the
	// duration of one forward pass and torn down by `flush` (record.go). It
	// is what makes a pass **one command buffer** rather than ~490: the
	// blocks' Run methods append to it instead of submitting.
	rec *recorder
}

// record installs the recorder on every block, so that everything from here
// to the matching `flush` is recorded rather than submitted. It is idempotent
// per pass and paired with `flush` on every return path, which is why the
// callers are the three entry points and not the layer loop.
func (g *Graph) record(rows int) {
	if g.rec == nil {
		g.rec = &recorder{}
	}
	g.rec.rows = rows
	g.hc.rec = g.rec
	g.move.rec = g.rec
	if g.ple != nil {
		g.ple.rec = g.rec
	}
	if g.dn != nil {
		g.dn.rec = g.rec
	}
	if g.attn != nil {
		g.attn.rec = g.rec
	}
	if g.moe != nil {
		g.moe.rec = g.rec
	}
	if g.head != nil {
		g.head.rec = g.rec
	}
}

// flush submits everything recorded and folds the GPU time each block's
// dispatches took into Stats. Every block goes back to submitting for itself
// afterwards, because the per-block benchmarks and the tests drive them
// directly and must not depend on a graph having been here.
//
// Nothing may read a device arena between `record` and here: the dispatches
// have not run. That is the one rule this arrangement adds, and the three
// entry points below are written around it — every `Mixed()`, `Logits()` and
// `Res()` is after the flush.
func (g *Graph) flush() error {
	if g.rec == nil {
		return nil
	}
	n := g.rec.len()
	t0 := time.Now()
	byOwner, byKind, total, err := g.rec.submit()
	submit := time.Since(t0)
	g.rec = nil
	g.hc.rec, g.move.rec = nil, nil
	if g.ple != nil {
		g.ple.rec = nil
	}
	if g.dn != nil {
		g.dn.rec = nil
	}
	if g.attn != nil {
		g.attn.rec = nil
	}
	if g.moe != nil {
		g.moe.rec = nil
	}
	if g.head != nil {
		g.head.rec = nil
	}
	if err != nil {
		return err
	}
	g.Stats.Dispatches += n
	g.Stats.GPU += total
	g.Stats.Submit += submit
	if g.Stats.Kinds == nil {
		g.Stats.Kinds = make(map[string]DispatchStat, len(byKind))
	}
	for k, v := range byKind {
		s := g.Stats.Kinds[k]
		s.Count, s.GPU = s.Count+v.Count, s.GPU+v.GPU
		g.Stats.Kinds[k] = s
	}
	g.Stats.HC += byOwner[ownHC]
	g.Stats.PLE += byOwner[ownPLE]
	g.Stats.DeltaNet += byOwner[ownDN]
	g.Stats.Attn += byOwner[ownAttn]
	g.Stats.MoE += byOwner[ownMoE]
	g.Stats.Head += byOwner[ownHead]
	g.Stats.Move += byOwner[ownMove]
	return nil
}

// PinSchedule fixes the hyper-connection block's kernel choice so that the
// graph runs the same arithmetic whatever the chunk length, and puts it back
// on the measured schedule when off.
//
// It exists for one equality and it is the equality L7b is about. Every rung
// of every ladder in this vertical used to be **bit-exact** against its
// siblings — they change how the work is tiled and never how a sum is
// associated — so "a prompt in chunks is the prompt whole" could be asserted
// to the last place even though a one-token chunk plans different kernels
// than a 128-token one. L7d's split-K GEMV is the first rung that is not:
// dividing a 10240-long dot product 160 ways and adding the pieces back is a
// different association of the same products, and at one token it is the rung
// the schedule picks. So the exactness claim is now conditional on the
// schedule, and this is what lets a test say which half it is testing.
// **L8d widened it.** The one-token kernels that stage replaces — the MoE's
// expert GEMVs, its split-K router and the split-K GEMV under the DeltaNet's
// two projections — are not bit-exact against the GEMMs they replace either,
// and for the same reason: a cooperative-matrix accumulator sums sixteen k an
// instruction in an order the extension does not define, a GEMV lane sums them
// serially, and a split-K reduce adds the slabs afterwards. So the pin now
// covers four blocks rather than one — **five with L8e**, which puts the
// full-attention layer's two projections on the same kernel.
func (g *Graph) PinSchedule(on bool) error {
	if g.moe != nil {
		g.moe.PinGemv(on)
	}
	if g.dn != nil {
		g.dn.PinGemv(on)
	}
	if g.attn != nil {
		g.attn.PinGemv(on)
	}
	if !on {
		g.hc.AutoPlan()
		return nil
	}
	return g.hc.SetPlan(HCDownM1, HCUpM4)
}

// ResetStats clears the accumulated timings.
func (g *Graph) ResetStats() { g.Stats = GraphStats{} }

// since adds the elapsed time to one of the stat fields and returns now, so a
// sequence of phases is a chain of one-line calls rather than a pile of
// start/stop pairs.
// blk routes a host interval to a block's stat field — except while a pass is
// being recorded, when the host is only building push constants and the
// block's real cost comes back from the GPU marks (record.go). Then the
// interval is what recording it cost, which is glue.
func (g *Graph) blk(dst *time.Duration, t0 time.Time) time.Time {
	if g.rec != nil {
		return since(&g.Stats.Glue, t0)
	}
	return since(dst, t0)
}

func since(dst *time.Duration, t0 time.Time) time.Time {
	now := time.Now()
	*dst += now.Sub(t0)
	return now
}

// GraphStats is where a prefill's wall clock went.
//
// The split that matters here is **block against glue**. Every block in this
// vertical owns its own arenas, so `hc_mixed` leaves one fp32 arena, is
// narrowed to halves on the host and is written into another — a memcpy
// between two mapped pointers of the same physical RAM on this machine, but
// one llama.cpp does not do. 96 of those a graph, each 2560 wide, plus the
// block outputs coming back. Fusing them away is a shared-arena change to
// five files; L6b's job is to say what they cost, not to hide them.
type GraphStats struct {
	Total time.Duration
	// Per block, the wall clock around its dispatches.
	HC, PLE, DeltaNet, Attn, MoE, Head time.Duration
	// The host side: the two gathers, and whatever still crosses a block
	// boundary through host memory.
	Gather, Glue time.Duration
	// Move is the arena-to-arena moves, on the device (L6c).
	Move time.Duration
	// Runs is how many prefills these totals cover.
	Runs int
	// GPU is what the pass's one command buffer took end to end, and
	// Dispatches how many dispatches went into it (L7d). The per-block rows
	// above are GPU time inside it and so sum to a little less than GPU
	// itself — the difference is what the barriers between dispatches cost.
	GPU        time.Duration
	Dispatches int
	// Submit is the **host** wall clock around the submit and the fence
	// wait — GPU is the part of it the timestamps saw, so `Submit - GPU` is
	// what handing one command buffer over costs (P1). It is separated from
	// the rest of the host side because it is the one interval a
	// pre-recorded command buffer would not remove.
	Submit time.Duration
	// Kinds is the same GPU time split by each dispatch's own label rather
	// than by the block it came from (P1). A decode step is ~490 dispatches
	// over about thirty distinct labels, so this is the resolution at which
	// "where does the token go" has an answer.
	Kinds map[string]DispatchStat
}

// Blocks is the time inside the five blocks and the head.
func (s GraphStats) Blocks() time.Duration {
	return s.HC + s.PLE + s.DeltaNet + s.Attn + s.MoE + s.Head
}

// StagedBlock is one row of the staging plan.
type StagedBlock struct {
	Name    string
	Layers  int
	Buffers int
	Weights int
	Arenas  int
	Elapsed time.Duration
}

// NewGraph stages the whole model and builds the order.
//
// The staging order is L6a-5's and for L6a-5's reason: the dense blocks are
// dequantised to f32 on the host on the way to the device, and the 36
// DeltaNet layers are 8.35 GB of transient floats at once, so they go first
// and their host copies are dropped between them. The 77 GB expert bank needs
// no host floats at all and goes last, which makes the peak the resident
// model rather than the resident model plus a dequantisation.
func NewGraph(dev *vk.Device, m *Model, opts GraphOpts) (*Graph, error) {
	c := m.Config
	if opts.MaxTokens <= 0 {
		return nil, fmt.Errorf("llm: graph MaxTokens is %d", opts.MaxTokens)
	}
	nLayer := c.NLayer
	if opts.Layers > 0 && opts.Layers < nLayer {
		nLayer = opts.Layers
	}
	nKV := opts.NKV
	if nKV < roundUpInt(opts.MaxTokens, 256) {
		nKV = roundUpInt(opts.MaxTokens, 256)
	}
	g := &Graph{m: m, cfg: c, nLayer: nLayer, maxTok: opts.MaxTokens, nKV: nKV}

	if err := g.stage(dev, opts); err != nil {
		g.Destroy()
		return nil, err
	}
	return g, nil
}

// stage puts every block on the device, in the order that keeps the peak down.
func (g *Graph) stage(dev *vk.Device, opts GraphOpts) error {
	m, c := g.m, g.cfg
	var err error
	if g.move, err = newMover(dev); err != nil {
		return err
	}
	mark := func(name string, layers, buffers, weights, arenas int, start time.Time) {
		g.Staged = append(g.Staged, StagedBlock{name, layers, buffers, weights, arenas, time.Since(start)})
	}

	// 1. The mixers: two a layer and the head's. Indexed 2L (attn), 2L+1
	//    (ffn), and 2*nLayer for the head — which is why the head is staged
	//    with them and not as a block of its own.
	start := time.Now()
	var mixers []HCWeights
	for l := 0; l < g.nLayer; l++ {
		for _, side := range []string{"attn", "ffn"} {
			w, err := m.HCWeights(l, side)
			if err != nil {
				return fmt.Errorf("llm: hc layer %d %s: %w", l, side, err)
			}
			mixers = append(mixers, w)
		}
	}
	head, err2 := m.HCWeights(-1, "")
	if err2 != nil {
		return fmt.Errorf("llm: hc head mixer: %w", err2)
	}
	mixers = append(mixers, head)
	// L8c-6's bank, where the plan names this family. `hc_attn_down` is the
	// tensor `simFamily` maps to "hyper_conn" and the checkpoint ships it as
	// Q8_0, which is what the `true` says; `inject` is F32 and stays in the
	// fp16 tail whatever this is (D13).
	hcOpts := HCBankOpts()
	hcOpts.Q8 = opts.denseQ8()
	if g.hc, err = NewHCGPU(dev, c.HCConfig(), g.maxTok, mixers, hcOpts); err != nil {
		return fmt.Errorf("llm: hc: %w", err)
	}
	mark("hyper-conn", len(mixers), g.hc.Buffers(), g.hc.WeightBytes(), g.hc.ActivationBytes(), start)
	mixers = nil
	freeHost()

	// 2. The PLE n-gram block, if this checkpoint has one. It is a single
	//    layer — layer 1 — and the 28.80 GB table it gathers from stays
	//    mmap'd (D2).
	pleCfg, ok, err := m.PLEConfig()
	if err != nil {
		return fmt.Errorf("llm: ple config: %w", err)
	}
	if ok && pleRuns(pleCfg, g.nLayer) {
		start = time.Now()
		w, err := m.PLEWeights(pleCfg.Layers[0])
		if err != nil {
			return fmt.Errorf("llm: ple layer %d: %w", pleCfg.Layers[0], err)
		}
		if g.ple, err = NewPLEGPU(dev, pleCfg, g.maxTok, w, PLEOpts{}); err != nil {
			return fmt.Errorf("llm: ple: %w", err)
		}
		g.pleCfg, g.hasPLE = pleCfg, true
		mark("ple n-gram", len(pleCfg.Layers), g.ple.Buffers(), g.ple.WeightBytes(), g.ple.ActivationBytes(), start)
		freeHost()
	}

	// 3 and 4. The two kinds of attention half, and the map from a layer to
	//    which of them it is. The interval is four, so 36 layers are the
	//    gated DeltaNet and 12 are full attention with the QSA indexer.
	g.kinds = make([]blockKind, g.nLayer)
	start = time.Now()
	var dnCfg DeltaNetConfig
	var dns []DeltaNetWeights
	for l := 0; l < g.nLayer; l++ {
		cfg, ok, err := m.DeltaNetConfig(l)
		if err != nil {
			return fmt.Errorf("llm: deltanet config %d: %w", l, err)
		}
		if !ok {
			continue
		}
		w, err := m.DeltaNetWeights(l)
		if err != nil {
			return fmt.Errorf("llm: deltanet layer %d: %w", l, err)
		}
		g.kinds[l] = blockKind{attn: false, idx: len(dns)}
		dnCfg, dns = cfg, append(dns, w)
	}
	if len(dns) > 0 {
		// L8c-5's bank, where the plan names this family. `attn_qkv` is the
		// tensor `simFamily` maps to "deltanet" and the checkpoint ships it
		// as Q8_0, which is what the `true` says — the block's own two F32
		// matrices stay in the fp16 tail whatever this is (D13).
		dnBank, dnSim := bankOf(opts.denseQ8()), QuantSim{}
		if q, ok := DenseBankPlan().For("blk.0.attn_qkv.weight", true); ok {
			dnBank, dnSim = BankQ4K, q
		}
		if g.dn, err = NewDeltaNetGPUBank(dev, dnCfg, g.maxTok, dns, dnBank, dnSim); err != nil {
			return fmt.Errorf("llm: deltanet: %w", err)
		}
		mark("deltanet", len(dns), g.dn.Buffers(), g.dn.WeightBytes(), g.dn.ActivationBytes(), start)
	}
	dns = nil
	freeHost()

	start = time.Now()
	var atCfg AttnConfig
	var ats []AttnWeights
	for l := 0; l < g.nLayer; l++ {
		cfg, ok, err := m.AttnConfig(l)
		if err != nil {
			return fmt.Errorf("llm: attn config %d: %w", l, err)
		}
		if !ok {
			continue
		}
		w, err := m.AttnWeights(l)
		if err != nil {
			return fmt.Errorf("llm: attn layer %d: %w", l, err)
		}
		g.kinds[l] = blockKind{attn: true, idx: len(ats)}
		atCfg, ats = cfg, append(ats, w)
	}
	if len(ats) > 0 {
		// L8c-7's bank, where the plan names this family. `attn_q` is the
		// tensor `simFamily` maps to "full_attn" and the checkpoint ships it
		// as Q8_0, which is what the `true` says; the indexer's two are
		// **BF16**, which is what the `false` says, and they are a family of
		// their own because L4b-4 measured the score sensitive to them.
		atBank, atSim := bankOf(opts.denseQ8()), QuantSim{}
		if q, ok := DenseBankPlan().For("blk.0.attn_q.weight", true); ok {
			atBank, atSim = BankQ4K, q
		}
		idxQ := false
		if q, ok := DenseBankPlan().For("blk.0.indexer.q_proj.weight", false); ok {
			if atBank != BankQ4K {
				return fmt.Errorf("llm: qsa_indexer is staged in the fused projection's plane, so it needs full_attn on the same bank")
			}
			if q != atSim {
				return fmt.Errorf("llm: full_attn is %s and qsa_indexer is %s, and they share one plane", atSim, q)
			}
			idxQ = true
		}
		if g.attn, err = NewAttnGPUBank(dev, atCfg, g.maxTok, g.nKV, ats, atBank, atSim, idxQ); err != nil {
			return fmt.Errorf("llm: attn: %w", err)
		}
		mark("attention", len(ats), g.attn.Buffers(), g.attn.WeightBytes(), g.attn.ActivationBytes(), start)
	}
	ats = nil
	freeHost()

	// 5. The head, before the 77 GB rather than after it: it is 2.54 GB of
	//    host floats in flight a slab at a time, and the bank it fills is the
	//    last dense allocation there is.
	if !opts.NoHead {
		start = time.Now()
		t, err := m.Set.Get("output.weight")
		if err != nil {
			return fmt.Errorf("llm: output.weight: %w", err)
		}
		headRows := opts.HeadRows
		if headRows <= 0 {
			headRows = 1
		}
		// L8c-4's bank, where the plan names this family. Everything else
		// is still the checkpoint's own width (D13): the 4.5-bit bank has a
		// kernel for a matrix whose k is a multiple of 256, which is every
		// dense weight here but the 320-wide hyper-connection pair.
		// `true` is "the checkpoint ships it as Q8_0", which `output.weight`
		// does — it is what `LLM_DENSE_BANK_SRC` would select on if this
		// plan ever grew one.
		bank, sim := bankOf(opts.denseQ8()), QuantSim{}
		if q, ok := DenseBankPlan().For(t.Name, true); ok {
			bank, sim = BankQ4K, q
		}
		if g.head, err = NewHeadGPUBank(dev, c.NEmbd, t, headRows, bank, sim); err != nil {
			return fmt.Errorf("llm: head: %w", err)
		}
		mark("lm head", 1, g.head.Buffers(), g.head.WeightBytes(), g.head.ActivationBytes(), start)
		freeHost()
	}

	// 6. The expert banks: 97% of the parameters, staged byte for byte out
	//    of the mmap'd checkpoint, one buffer a layer.
	start = time.Now()
	var moes []MoEWeights
	for l := 0; l < g.nLayer; l++ {
		w, err := m.MoEWeights(l)
		if err != nil {
			return fmt.Errorf("llm: moe layer %d: %w", l, err)
		}
		moes = append(moes, w)
	}
	if g.moe, err = NewMoEGPU(dev, m.MoEConfig(), g.maxTok, moes); err != nil {
		return fmt.Errorf("llm: moe: %w", err)
	}
	mark("moe", len(moes), g.moe.Buffers(), g.moe.WeightBytes(), g.moe.ActivationBytes(), start)
	moes = nil
	freeHost()
	return nil
}

// Layers is how many layers this graph runs, NKV its cache, MaxTokens its
// arenas.
func (g *Graph) Layers() int    { return g.nLayer }
func (g *Graph) NKV() int       { return g.nKV }
func (g *Graph) MaxTokens() int { return g.maxTok }

// Head is the staged output projection, or nil when the graph was built
// without one.
func (g *Graph) Head() *HeadGPU { return g.head }

// Past is how many tokens of the current sequence are behind the graph, and
// Ids is that sequence.
func (g *Graph) Past() int    { return g.past }
func (g *Graph) Ids() []int32 { return g.ids }

// Reset starts a fresh sequence: the attention cache from cell zero, the PLE
// convolution from position zero, and every DeltaNet layer's recurrent state
// and window cleared (L7b).
//
// Only the DeltaNet's state is actually written. The other two are *masked*
// rather than cleared — a cell past the end of the sequence is excluded from
// every score, a convolution tap before position zero contributes nothing —
// so clearing them would be work that changes no output.
func (g *Graph) Reset() error {
	g.past = 0
	g.ids = g.ids[:0]
	if g.attn != nil {
		g.attn.Reset()
	}
	if g.ple != nil {
		g.ple.Reset()
	}
	if g.dn != nil {
		for l := 0; l < g.nLayer; l++ {
			if k := g.kinds[l]; !k.attn {
				if err := g.dn.Reset(k.idx); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// Forward runs the whole model over a prompt **as a fresh sequence** and
// returns the logits of its last token, which is the only row llama.cpp
// computes at prefill.
//
// It also returns `result_norm` — the final mixer's output, the tensor the
// head reads — because a logit disagreement has exactly two places to be and
// the caller should not have to run the graph twice to find out which.
func (g *Graph) Forward(ids []int32) (logits, norm []float32, err error) {
	if err := g.Reset(); err != nil {
		return nil, nil, err
	}
	return g.Extend(ids)
}

// Extend runs the model over the next tokens of the sequence the graph is
// already holding, and returns the last one's logits.
//
// It is Forward without the reset, and it is the whole of decode: a prompt is
// one call with many tokens, a generated token is a call with one. What makes
// the two the same computation is L7a's cache and L7b's two carried
// histories, and what asserts it is TestGraphIsAChunkSplit.
func (g *Graph) Extend(ids []int32) (logits, norm []float32, err error) {
	if g.head == nil {
		return nil, nil, fmt.Errorf("llm: this graph was staged without a head")
	}
	// One command buffer for the whole of it, head included (L7d): the
	// layers, the head mixer and the projection are recorded and submitted
	// once, and the two read-backs below are after the flush because nothing
	// has run until then.
	g.record(len(ids))
	defer func() {
		if ferr := g.flush(); ferr != nil && err == nil {
			logits, norm, err = nil, nil, ferr
		}
	}()
	if err := g.hidden(ids); err != nil {
		return nil, nil, err
	}
	top := time.Now()
	t0 := top
	if err := g.head.Resize(1); err != nil {
		return nil, nil, err
	}
	t0 = since(&g.Stats.Glue, t0)
	if err := g.move.Move(g.head.InPort(), g.hc.MixedPort(), 1); err != nil {
		return nil, nil, err
	}
	t0 = g.blk(&g.Stats.Move, t0)
	if err := g.head.Run(); err != nil {
		return nil, nil, err
	}
	g.blk(&g.Stats.Head, t0)
	// The flush is where the pass actually runs, and what it takes is
	// Stats.GPU plus the hand-over — so the clock restarts after it rather
	// than folding a whole forward pass into the glue.
	if err := g.flush(); err != nil {
		return nil, nil, err
	}
	t0 = time.Now()
	logits, norm = g.head.Logits(), g.hc.Mixed()
	since(&g.Stats.Glue, t0)
	g.Stats.Total += time.Since(top)
	return logits, norm, nil
}

// ForwardRows runs the model over a prompt as a fresh sequence and hands
// every row's logits from `first` on to fn, a head-arena slab at a time.
//
// It is Forward without `inp_out_ids`, and it exists because perplexity is
// the one question in this vertical that needs a logit per token. The
// reference's graph drops every row but the last before the final mixer, so
// `hidden` moves one row to the front and runs the mixer and the head on it;
// here the mixer runs over the whole batch — it is per token, so that is the
// same arithmetic on nTok times the work — and the head then runs over slabs
// of GraphOpts.HeadRows, because a row of logits is 0.99 MB and nothing
// reads two of them at once.
//
// fn sees a slice into the head's mapped arena and must not keep it: the
// next slab overwrites it.
func (g *Graph) ForwardRows(ids []int32, first int, fn func(t int, logits []float32) error) error {
	if g.head == nil {
		return fmt.Errorf("llm: this graph was staged without a head")
	}
	if first < 0 || first >= len(ids) {
		return fmt.Errorf("llm: first row %d of %d tokens", first, len(ids))
	}
	if err := g.Reset(); err != nil {
		return err
	}
	top := time.Now()
	g.record(len(ids))
	if err := g.appendN(ids, g.nLayer); err != nil {
		_ = g.flush()
		return err
	}
	t0 := time.Now()
	if err := g.hc.Run(2*g.nLayer, false); err != nil {
		_ = g.flush()
		return fmt.Errorf("llm: head mixer: %w", err)
	}
	g.blk(&g.Stats.HC, t0)
	if err := g.flush(); err != nil {
		return err
	}

	// The head, a slab at a time. Each slab is its own command buffer
	// because the logits have to be read between them, and nothing may read
	// a device arena while a pass is being recorded (flush's one rule).
	slab, vocab := g.head.MaxRows(), g.head.Vocab()
	for r0 := first; r0 < len(ids); r0 += slab {
		n := minInt(slab, len(ids)-r0)
		g.record(n)
		err := func() error {
			if err := g.head.Resize(n); err != nil {
				return err
			}
			if err := g.move.Move(g.head.InPort(), g.hc.MixedRowPort(r0), n); err != nil {
				return err
			}
			return g.head.Run()
		}()
		if ferr := g.flush(); err == nil {
			err = ferr
		}
		if err != nil {
			return err
		}
		lg := g.head.Logits()
		for i := 0; i < n; i++ {
			if err := fn(r0+i, lg[i*vocab:(i+1)*vocab]); err != nil {
				return err
			}
		}
	}
	g.Stats.Total += time.Since(top)
	return nil
}

// Hidden runs every layer and the final mixer over a fresh sequence, and
// returns `result_norm` for the last token: [nEmbd].
func (g *Graph) Hidden(ids []int32) ([]float32, error) {
	if err := g.Reset(); err != nil {
		return nil, err
	}
	return g.HiddenExtend(ids)
}

// HiddenExtend is Hidden without the reset: the next tokens of the sequence
// the graph is already holding.
func (g *Graph) HiddenExtend(ids []int32) ([]float32, error) {
	top := time.Now()
	g.record(len(ids))
	if err := g.hidden(ids); err != nil {
		_ = g.flush()
		return nil, err
	}
	if err := g.flush(); err != nil {
		return nil, err
	}
	t0 := time.Now()
	norm := g.hc.Mixed()
	since(&g.Stats.Glue, t0)
	g.Stats.Total += time.Since(top)
	return norm, nil
}

// hidden is HiddenExtend's body, without the read-back and without the
// submit: every layer, then the final mixer over the last token alone. It is
// separate so that Extend can go on recording through the head rather than
// flushing twice (L7d).
func (g *Graph) hidden(ids []int32) error {
	if err := g.appendN(ids, g.nLayer); err != nil {
		return err
	}
	top := time.Now()
	t0 := top
	// `inp_out_ids`: everything below is per token, so the reference drops
	// every row but the last before the final mixer. Here that is a move of
	// one row of the residual to the front of the same arena, and the mixer
	// then runs as a one-token pass — the same arithmetic on 1/nTok of the
	// work, which is what makes `result_norm` comparable against a trace
	// that holds one row.
	last := g.hc.ResRowPort(len(ids) - 1)
	if err := g.hc.Resize(1); err != nil {
		return err
	}
	t0 = since(&g.Stats.Glue, t0)
	if err := g.move.Move(g.hc.ResRowPort(0), last, 1); err != nil {
		return err
	}
	t0 = g.blk(&g.Stats.Move, t0)
	if err := g.hc.Run(2*g.nLayer, false); err != nil {
		return fmt.Errorf("llm: head mixer: %w", err)
	}
	g.blk(&g.Stats.HC, t0)
	return nil
}

// Residual is the wide residual as the last Prefill left it: [T][hc*nEmbd],
// which is `l_last` of the last layer the graph ran.
//
// It is the tensor a truncated graph is checked against. `Layers: 4` against
// `l_last-3` is the whole order — the embedding, the init, the PLE block at
// layer 1, three DeltaNet layers, one full-attention layer, four MoE blocks
// and eight mixers — for a tenth of the staging and none of the 77 GB the
// other 44 layers need.
func (g *Graph) Residual() []float32 { return g.hc.Res() }

// Prefill runs every layer over a prompt **as a fresh sequence**, leaving the
// wide residual in the hyper-connection block's arena.
func (g *Graph) Prefill(ids []int32) error {
	if err := g.Reset(); err != nil {
		return err
	}
	return g.Append(ids)
}

// PrefillN runs the first nLayer layers of a fresh sequence and stops.
//
// It is how the graph is asked a question the trace can answer. The oracle
// holds `l_last-0` through `l_last-3` and nothing deeper, so "does our error
// accumulate with depth or is there a bug at the bottom" is a question about
// four numbers — and four numbers are only a trend if the same staged model
// produces all of them.
func (g *Graph) PrefillN(ids []int32, nLayer int) error {
	if err := g.Reset(); err != nil {
		return err
	}
	return g.AppendN(ids, nLayer)
}

// Append runs every layer over the next tokens of the sequence the graph is
// holding, and advances it.
func (g *Graph) Append(ids []int32) error { return g.AppendN(ids, g.nLayer) }

// AppendN runs the first nLayer layers over the next tokens of the sequence.
//
// Three things make this a continuation rather than a second prompt, and all
// three are somewhere else: the attention cache and the indexer's pooled
// blocks (L7a), the PLE convolution's ring (L7b), and every DeltaNet layer's
// recurrent state and window, which were already carried across a batch split
// at L3 and only ever needed the graph to stop clearing them. What is left
// here is the n-gram gather — a trigram, so the first token of a continuing
// run still reads two tokens that are not in it, which is why the graph keeps
// the whole id list and hashes over all of it.
func (g *Graph) AppendN(ids []int32, nLayer int) error {
	top := time.Now()
	g.record(len(ids))
	if err := g.appendN(ids, nLayer); err != nil {
		_ = g.flush()
		return err
	}
	err := g.flush()
	g.Stats.Total += time.Since(top)
	return err
}

// appendN is that body without the record/flush pair, for the entry points
// that go on recording past the layers (L7d).
func (g *Graph) appendN(ids []int32, nLayer int) error {
	if nLayer <= 0 || nLayer > g.nLayer {
		return fmt.Errorf("llm: %d layers, this graph staged %d", nLayer, g.nLayer)
	}
	nTok := len(ids)
	if nTok <= 0 || nTok > g.maxTok {
		return fmt.Errorf("llm: %d tokens, the arenas are built for %d", nTok, g.maxTok)
	}
	if g.past+nTok > g.nKV {
		return fmt.Errorf("llm: %d tokens at position %d of a %d-cell context", nTok, g.past, g.nKV)
	}

	top := time.Now()
	t0 := top

	// The embedding gather, and the n-gram one beside it. Both are host-side
	// reads out of the mmap'd checkpoint: `token_embd` is 675 MB of which a
	// prompt touches nTok rows, and the n-gram table is 28.80 GB of which it
	// touches nTok*16 — and that one has to stay on the host, because D2
	// keeps the table off the device entirely.
	embd, err := g.m.Embeddings(ids)
	if err != nil {
		return fmt.Errorf("llm: token_embd: %w", err)
	}
	g.ids = append(g.ids, ids...)
	var pleEmbd []float32
	if g.hasPLE {
		// Hashed over the whole sequence, gathered for its tail: the trigram
		// of the first token of this run reaches two tokens behind it.
		rows := PLERows(g.pleCfg, g.ids)[g.past*g.pleCfg.NHeads:]
		pleEmbd, err = g.m.PLEGather(rows, g.pleCfg.NHeads, g.pleCfg.HeadDim)
		if err != nil {
			return fmt.Errorf("llm: per_layer_token_embd: %w", err)
		}
	}
	t0 = since(&g.Stats.Gather, t0)

	// The wide residual starts as hc identical copies of the embedding, and
	// from here it lives in the hyper-connection block's arena: every
	// combine updates it in place and nothing else in the graph writes it.
	// It is per *batch* and not per sequence — the stream is a function of
	// the token, and what carries between runs is the three histories above.
	// This is the last host *write* of the pass — a write costs 70 GB/s
	// where a read costs 25 (L6b-4), and the embedding is on the host
	// anyway.
	if err := g.hc.UploadInit(embd, nTok); err != nil {
		return err
	}
	if g.attn != nil {
		if err := g.attn.SetPast(g.past); err != nil {
			return err
		}
	}
	if g.ple != nil {
		if err := g.ple.SetPast(g.past); err != nil {
			return err
		}
	}
	if g.dn != nil {
		if err := g.dn.SetPast(g.past); err != nil {
			return err
		}
	}
	t0 = since(&g.Stats.Glue, t0)

	// P1a's fusion, as a scheduling rule rather than a kernel choice. A
	// combine and the next mixer's norm are the same 2560 values per
	// (token, stream) read, written and read again, so `RunCombineMix` does
	// both in one dispatch — but only where nothing else touches the wide
	// residual in between. So a combine is *held* rather than issued, and
	// whatever comes next either absorbs it or flushes it: the PLE block,
	// which moves the residual out of this arena and back, flushes; the end
	// of the pass flushes, because the final mixer is reached through a row
	// move in `hidden`. Everything else absorbs, which is 94 of the 96.
	pending := -1
	flushHC := func() error {
		if pending < 0 {
			return nil
		}
		m := pending
		pending = -1
		return g.hc.RunCombine(m)
	}
	fuse := HCFuse()
	mixHC := func(m int) error {
		if pending < 0 {
			return g.hc.Run(m, false)
		}
		if !fuse {
			if err := flushHC(); err != nil {
				return err
			}
			return g.hc.Run(m, false)
		}
		p := pending
		pending = -1
		return g.hc.RunCombineMix(p, m)
	}

	for l := 0; l < nLayer; l++ {
		if g.hasPLE && g.pleCfg.IsPLE(l) {
			// The one block that reads and writes the wide residual, so the
			// only place the 10240-wide tensor crosses a boundary — twice,
			// once a graph.
			if err := flushHC(); err != nil {
				return fmt.Errorf("llm: layer %d ple combine: %w", l, err)
			}
			t0 = g.blk(&g.Stats.HC, t0)
			if err := g.ple.UploadEmbd(pleEmbd, nTok); err != nil {
				return err
			}
			t0 = since(&g.Stats.Glue, t0)
			if err := g.move.Move(g.ple.ResPort(), g.hc.ResPort(), nTok); err != nil {
				return err
			}
			t0 = g.blk(&g.Stats.Move, t0)
			if err := g.ple.Run(); err != nil {
				return err
			}
			t0 = g.blk(&g.Stats.PLE, t0)
			if err := g.move.Move(g.hc.ResPort(), g.ple.ResPort(), nTok); err != nil {
				return err
			}
			t0 = g.blk(&g.Stats.Move, t0)
		}

		// The attention half.
		if err := mixHC(2 * l); err != nil {
			return fmt.Errorf("llm: layer %d attn mix: %w", l, err)
		}
		t0 = g.blk(&g.Stats.HC, t0)
		t1, err := g.sublayer(l, nTok, t0)
		if err != nil {
			return err
		}
		t0 = t1
		pending = 2 * l

		// The FFN half, which every layer has.
		if err := mixHC(2*l + 1); err != nil {
			return fmt.Errorf("llm: layer %d ffn mix: %w", l, err)
		}
		t0 = g.blk(&g.Stats.HC, t0)
		if err := g.moe.Resize(nTok); err != nil {
			return err
		}
		t0 = since(&g.Stats.Glue, t0)
		if err := g.move.Move(g.moe.InPort(), g.hc.MixedPort(), nTok); err != nil {
			return err
		}
		t0 = g.blk(&g.Stats.Move, t0)
		if err := g.moe.Run(l); err != nil {
			return fmt.Errorf("llm: layer %d moe: %w", l, err)
		}
		t0 = g.blk(&g.Stats.MoE, t0)
		if err := g.move.Move(g.hc.BlockOutPort(), g.moe.OutPort(), nTok); err != nil {
			return err
		}
		t0 = g.blk(&g.Stats.Move, t0)
		pending = 2*l + 1
	}
	if err := flushHC(); err != nil {
		return fmt.Errorf("llm: last combine: %w", err)
	}
	t0 = g.blk(&g.Stats.HC, t0)
	g.past += nTok
	g.Stats.Runs++
	return nil
}

// sublayer runs one layer's attention half — the gated DeltaNet in 36 layers
// of 48, full attention with the QSA indexer in the other 12 — leaving its
// output in the hyper-connection block's arena for the combine, and returning
// the clock it left off at.
//
// Nothing here is a host tensor. The mixer's output is moved into the layer's
// fp16 A operand by one dispatch and the layer's output is moved back by
// another; `Resize` is only the length of the run and whatever a Move will
// not reach.
func (g *Graph) sublayer(l, nTok int, t0 time.Time) (time.Time, error) {
	k := g.kinds[l]
	var in, out Port
	var run func() error
	if k.attn {
		if err := g.attn.Resize(nTok); err != nil {
			return t0, err
		}
		in, out = g.attn.InPort(), g.attn.OutPort()
		run = func() error { return g.attn.Run(k.idx) }
	} else {
		if err := g.dn.Resize(nTok); err != nil {
			return t0, err
		}
		in, out = g.dn.InPort(), g.dn.OutPort()
		run = func() error { return g.dn.Run(k.idx) }
	}
	t0 = since(&g.Stats.Glue, t0)
	if err := g.move.Move(in, g.hc.MixedPort(), nTok); err != nil {
		return t0, err
	}
	t0 = g.blk(&g.Stats.Move, t0)
	if err := run(); err != nil {
		return t0, fmt.Errorf("llm: layer %d sublayer: %w", l, err)
	}
	if k.attn {
		t0 = g.blk(&g.Stats.Attn, t0)
	} else {
		t0 = g.blk(&g.Stats.DeltaNet, t0)
	}
	if err := g.move.Move(g.hc.BlockOutPort(), out, nTok); err != nil {
		return t0, err
	}
	return g.blk(&g.Stats.Move, t0), nil
}

// Destroy releases every block.
func (g *Graph) Destroy() {
	if g.move != nil {
		g.move.Destroy()
	}
	if g.head != nil {
		g.head.Destroy()
	}
	if g.moe != nil {
		g.moe.Destroy()
	}
	if g.attn != nil {
		g.attn.Destroy()
	}
	if g.dn != nil {
		g.dn.Destroy()
	}
	if g.ple != nil {
		g.ple.Destroy()
	}
	if g.hc != nil {
		g.hc.Destroy()
	}
}

// pleRuns reports whether any PLE layer falls inside a truncated graph.
func pleRuns(c PLEConfig, nLayer int) bool {
	for _, l := range c.Layers {
		if int(l) < nLayer {
			return true
		}
	}
	return false
}

// freeHost returns the floats a block was staged from to the operating system
// before the next block asks for its own.
//
// It matters here and nowhere else in this package, for L6a-5's reason: the
// dense half is dequantised to f32 on the way to the device and the 36
// DeltaNet layers are 8.35 GB of that at once, so a staging that does not
// give them back peaks at the resident model plus a dequantisation.
func freeHost() {
	runtime.GC()
	debug.FreeOSMemory()
}

