	GammaKOff, GammaIQOff, GammaIKOff uint32
	Heads, KVHeads, HeadDim           uint32
	NKV, Plane, LDCtx                 uint32
	IdxHeads, IdxDim                  uint32
	SelOff, SelWidth                  uint32
	Ratio, RotDims                    uint32
	AttnScale                         uint32

