235	                                    const void *pushConstants, uint32_t pushConstantSize,
236	                                    uint64_t *out_start, uint64_t *out_end, uint64_t *out_marks);
237	
238	void shim_destroy_compute_pipeline(VkDevice device, ShimComputePipeline *p);
239	
240	#endif
