func (g *AttnGPU) OutPort() Port {
	return Port{Buf: g.abuf, Off: g.aOut, Stride: g.cfg.NEmbd, Width: g.cfg.NEmbd}
}

// Resize sets the length of the run without writing the input.
func (g *AttnGPU) Resize(nTok int) error {
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, arenas are built for %d", nTok, g.tokens)
	}
	g.rows = nTok
	if g.autoPlan {
		g.gemm, g.outGemm = GEMMKernelFor(nTok), OutGEMMKernelFor(nTok)
		if g.pinGemv {
			g.qkvGemv, g.outGemv = GEMVOff, GEMVOff
		} else {
			g.qkvGemv, g.outGemv = AttnGemvFor(nTok)
		}
	}
// Resize sets the length of the run and clears what a Move will not reach.
//
// The context operand's pad rows are the part that matters: `llm_dn_norm`
// writes only the run's tokens into `hCtx`, so a shorter run after a longer
// one would leave the output projection reading the longer one's tail.
func (g *DeltaNetGPU) Resize(nTok int) error {
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, arenas are built for %d", nTok, g.tokens)
	}
	g.rows = nTok
	if g.autoPlan {
		g.gemm, g.outGemm = GEMMKernelFor(nTok), OutGEMMKernelFor(nTok)
		if g.pinGemv {
			g.qkvGemv, g.outGemv = GEMVOff, GEMVOff
		} else {
			g.qkvGemv, g.outGemv = DNGemvFor(nTok)
		}
	}
	if pad := g.arenaRows - nTok; pad > 0 {
		g.hbuf.ZeroUint16At(int(g.hCtx)+nTok*g.ldCtx, pad*g.ldCtx)
	}
}

// Resize sets the length of the run and writes the shared expert's own
// permutation and schedule, which are the identity over the run's tokens and
// so stay host-side however the input arrives.
func (g *MoEGPU) Resize(nTok int) error {
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, staged for %d", nTok, g.tokens)
	}
	if !g.autoPlan {
		if err := moeCheckGemv(g.up, g.down, nTok); err != nil {
			return err
		}
		if err := moeCheckGemv(g.shUp, g.shDown, nTok); err != nil {
			return err
		}
	}
	g.rows = nTok
	if g.autoPlan {
		g.router = GEMMKernelFor(nTok)
		g.up, g.down, g.routerGemv = g.moePlan(nTok)
		g.shUp, g.shDown = g.moeSharedPlan(nTok)
	}
	g.syncShared()
	return nil
}
		Rows: g.arenaRows, Half: true}
}

// Resize sets how many rows the projection covers, without writing them.
func (g *HeadGPU) Resize(rows int) error {
	if rows <= 0 || rows > g.tokens {
		return fmt.Errorf("llm: %d rows, the head arena is built for %d", rows, g.tokens)
	}
	if g.gemv != GEMVOff && rows != 1 {
		return fmt.Errorf("llm: the GEMV reads one row, not %d (D15)", rows)
	}
	g.rows = rows
	if g.autoPlan {
		g.gemm = OutGEMMKernelFor(rows)
	}
	return nil
}
	wide := g.cfg.Wide()
	return Port{Buf: g.abuf, Off: g.aRes + uint32(t*wide), Stride: wide, Width: wide, Rows: 1}
}

// Resize sets the length of the run without writing the residual, for a
// caller that is about to fill it with a Move rather than an Upload.
func (g *HCGPU) Resize(nTok int) error {
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, arenas are built for %d", nTok, g.tokens)
	}
	g.rows = nTok
	if g.autoPlan {
		g.down, g.up = PlanForBank(nTok, g.dbank)
	}
	return nil
}
func (g *HCGPU) UploadInit(embd []float32, nTok int) error {
	c := g.cfg
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, arenas are built for %d", nTok, g.tokens)
	}
	if len(embd) != nTok*c.NEmbd {
		return fmt.Errorf("llm: embedding is %d values, want %d", len(embd), nTok*c.NEmbd)
	}
	if err := g.Resize(nTok); err != nil {
		return err
	}
	for t := 0; t < nTok; t++ {
		row := embd[t*c.NEmbd : (t+1)*c.NEmbd]
		for ch := 0; ch < c.HC; ch++ {
			g.abuf.WriteFloat32At(int(g.aRes)+(t*c.HC+ch)*c.NEmbd, row)
		}
	}
	return nil
}

// UploadBlockOut writes the block output the combine scatters back.
func (g *HCGPU) UploadBlockOut(out []float32) error {
	if len(out) != g.rows*g.cfg.NEmbd {
		return fmt.Errorf("llm: block output is %d values, want %d", len(out), g.rows*g.cfg.NEmbd)
	}
	g.abuf.WriteFloat32At(int(g.aOut), out)
	return nil
}

// graph builds one mixer's dispatch sequence, with a label per dispatch, and
// is shared by Run and Profile so that what the profiler times is what a run
// executes. combine appends the scatter, which needs a block output.
//
func (g *PLEGPU) ResPort() Port {
	return Port{Buf: g.abuf, Off: g.aRes, Stride: g.cfg.Wide(), Width: g.cfg.Wide(), Rows: g.rows}
}

// UploadEmbd writes the gathered n-gram embedding alone, for a caller that is
// filling the residual with a Move rather than an Upload.
func (g *PLEGPU) UploadEmbd(embd []float32, nTok int) error {
	c := g.cfg
	if nTok <= 0 || nTok > g.tokens {
		return fmt.Errorf("llm: %d tokens, arenas are built for %d", nTok, g.tokens)
	}
	if len(embd) != nTok*c.EmbdWidth() {
		return fmt.Errorf("llm: embedding is %d values, want %d", len(embd), nTok*c.EmbdWidth())
	}
	g.rows = nTok
	if g.autoKernel {
		g.kv = PLEKernelFor(nTok)
	}
	slab := make([]uint16, nTok*g.lda)
